            {
               break;
            }
            if(this._gemBag[i] != null)
            {
               if((this._gemBag[i] as Gem).compareById(id))
               {
                  if(this._gemBag[i].getIsPile() == true)
                  {
                     for(t = 1; t <= times; t++)
                     {
                        (this._gemBag[i] as Gem).useGem(1);
