         }
         var str2:String = str;
         if(str == "站立")
         {
            str2 = "站立" + int(Math.random() * 3 + 1);
         }
         else if(str == "攻击")
         {
            arr = data.getPetSkillType();
            xx = int(Math.random() * 4);
            if(arr[xx] <= 0)
            {
               gongJiYn1 = gongJiYn2 = false;
