methods.before_method:
public function GoTo(str:String, YN:Boolean = false) : *
      {
         var arr:Array = null;
         var xx:int = 0;
         if(noMove)
         {
            return;
         }
         var num:uint = 3;
         if(data._id.getValue() == 73105)
         {
            num = 5;
         }
         var str2:String = str;
         if(str == "站立")
         {
            str2 = "站立" + int(Math.random() * num + 1);
         }
         else if(str == "攻击")
         {
            arr = data.getPetSkillType();
            xx = int(Math.random() * 4);
            if(arr[xx] <= 0)
            {
               gongJiYn1 = gongJiYn2 = false;
               return;
            }
            str2 = "攻击" + arr[xx];
         }
         if(runType != str2 && (isRunOver() || YN))
         {
            runType = str2;
            runType2 = str;
            trace("GoToGoToGoTo ==== " + runType);
            if(str == "攻击")
            {
               noMove = true;
               timeNum = 27 * 10;
               gongJiYn1 = gongJiYn2 = false;
            }
            skin.gotoAndPlay(runType);
         }
      }

