         var crit:Number = 0;
         for(var i:* = 0; i < 8; i++)
         {
            if(who.skinNum == 0)
            {
               if(i == 5)
               {
                  continue;
               }
            }
            else if(who.skinNum == 1)
            {
               if(i == 2)
               {
                  continue;
               }
            }
            if(_slot[i] != null)
            {
